import useDocumentSize from '@cetus/hooks/src/useDocumentSize'
import useQueryParams from '@cetus/hooks/src/useQueryParams'
import { Icon } from '@cetus/ui-kit'
import { Box, Button, Divider, HStack, MenuButton, MenuListProps, PlacementWithLogical, Skeleton, Spinner, Text, VStack } from '@chakra-ui/react'
import { cloneElement, useEffect, useState } from 'react'
import CetusMenu from '../CetusMenu'
import { baseFeeStepConfig, feeConfigs } from './config'
import { BinStepType, DlmmFeeAndBinStepSelectProps, DlmmSelectFeeType } from './type'

export default function DlmmFeeAndBinStepSelect({
  baseFee,
  onBaseFeeChange,
  binStep,
  binStepList,
  onBinStepChange,
  loading,
  disabled,
  isShowSelect = true,
  feeOptions = [],
  changeLoading = false
}: DlmmFeeAndBinStepSelectProps) {
  const { size } = useDocumentSize()
  const { title, label, color } = feeConfigs['dlmm']
  const [originBaseFee, setOriginBaseFee] = useState<any>()
  const [originBinStep, setOriginBinStep] = useState<any>()
  const { poolId } = useQueryParams()
  useEffect(() => {
    if (!originBaseFee) {
      setOriginBaseFee(baseFee)
    }
    if (binStep) {
      setOriginBinStep(binStep)
    }
  }, [baseFee, binStep])

  return (
    <DlmmSelectDrop
      baseFee={baseFee}
      onBaseFeeChange={onBaseFeeChange}
      binStep={binStep}
      binStepList={binStepList || []}
      onBinStepChange={onBinStepChange}
      feeOptions={feeOptions}
      changeLoading={changeLoading}
    >
      {({ isOpen, onClick }) => (
        <MenuButton
          as={Button}
          variant="unstyled"
          isDisabled={disabled || loading}
          p="3px 3px 3px 8px"
          borderRadius="8px"
          border="1px solid"
          borderColor="border"
          display="flex"
          bg="bg_secondary"
          justifyContent="space-between"
          h={{ base: '40px', lg: '32px' }}
          w={{ base: '100%', lg: 'auto' }}
          cursor="pointer"
          onClick={() => {
            if (isShowSelect) {
              onClick()
            }
          }}
        >
          <HStack w="100%" h={{ base: '32px', lg: '24px' }} justify={{ base: 'space-between', lg: 'center' }}>
            <Text color="primary" fontSize={{ base: '14px', lg: '12px' }} fontWeight="500">
              {title}
            </Text>
            {loading ? (
              <Skeleton w="84px" h={{ base: '32px', lg: '24px' }} />
            ) : (
              <HStack borderRadius="4px" bg="primary_opacity.10" p="5px 8px" gap="4px">
                {label && <Text fontSize="12px">{label}</Text>}
                <>
                  <Text color="primary" fontSize="14px">
                    {originBaseFee?.feeDisplay || '--%'}
                  </Text>
                  <Divider orientation="vertical" h="10px" borderColor="white_color_opacity.30" />
                  <Text color="primary" fontSize="14px">
                    {originBinStep?.binStep || baseFeeStepConfig[originBaseFee?.fee || '']} bps
                  </Text>
                </>

                {isShowSelect ? (
                  <Icon
                    fontSize="12px"
                    xlinkHref="#icon-icon_arrow"
                    transition="transform 0.5s"
                    transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
                  />
                ) : null}
              </HStack>
            )}
          </HStack>
        </MenuButton>
      )}
    </DlmmSelectDrop>
  )
}

type DlmmSelectDropProps = {
  baseFee: Pick<BinStepType, 'fee' | 'feeDisplay'> | undefined
  onBaseFeeChange: (value: Pick<BinStepType, 'fee' | 'feeDisplay'>) => void
  onBinStepChange: (value: any, hasEffect: boolean) => void
  binStep: any
  binStepList: any[]
  children: (props: any) => JSX.Element
  wrapStyle?: MenuListProps
  placement?: PlacementWithLogical
  feeOptions: DlmmSelectFeeType[]
  changeLoading: boolean
}
const DlmmSelectDrop = ({
  baseFee,
  onBaseFeeChange,
  onBinStepChange,
  binStep,
  binStepList,
  children,
  wrapStyle,
  placement,
  feeOptions,
  changeLoading
}: DlmmSelectDropProps) => {
  const [open, setOpen] = useState(false)
  const [loadingKey, setLoadingKey] = useState<string>('')
  const [originBaseFee, setOriginBaseFee] = useState<any>()
  const [originBinStep, setOriginBinStep] = useState<any>()

  useEffect(() => {
    if (open) {
      document.querySelector('.active_fee')?.scrollIntoView()
    }
  }, [open])

  useEffect(() => {
    if (open && baseFee) {
      document.querySelector('.active_bin_step')?.scrollIntoView()
    }
  }, [baseFee, open])

  useEffect(() => {
    setOriginBaseFee(baseFee)
    setOriginBinStep(binStep)
  }, [])
  return (
    <CetusMenu
      isLazy
      isOpen={open}
      onClose={() => {
        if (binStep === undefined) {
          onBaseFeeChange(originBaseFee)
          onBinStepChange(originBinStep, false)
        }
        setOpen(false)
      }}
      placement={placement}
      defaultMaxH="315px"
      listProps={{
        p: '8px',
        borderRadius: '12px',
        w: { base: 'calc(100vw - 24px)', lg: '280px' },
        overflowY: 'hidden',
        ...wrapStyle
      }}
    >
      {typeof children === 'function'
        ? children({
            isOpen: open,
            onClick: () => setOpen(!open)
          })
        : cloneElement(children, {
            isOpen: open,
            onClick: () => setOpen(!open)
          })}
      <HStack align="flex-start" gap="4px">
        <VStack h="100%" gap="8px" align="flex-start" justify="flex-start">
          <Text h="20px" lineHeight="20px" fontSize="14px">
            Base Fee
          </Text>
          <VStack h="232px" overflowY="auto" align="flex-start">
            {feeOptions?.map(item => (
              <Box
                w="100%"
                key={item?.fee}
                onClick={() => onBaseFeeChange(item)}
                h="40px"
                p="13px 12px"
                borderRadius="8px"
                fontSize="14px"
                textAlign="start"
                color={item?.fee === baseFee?.fee + '' ? 'primary' : 'text_caption'}
                bg={item?.fee === baseFee?.fee + '' ? 'bg_six' : 'transparent'}
                className={item?.fee === baseFee?.fee + '' ? 'active_fee' : 'inactive_fee'}
                cursor="pointer"
                _hover={{
                  color: 'primary'
                }}
              >
                {item?.feeDisplay}
              </Box>
            ))}
          </VStack>
        </VStack>
        {baseFee && (
          <VStack h="100%" gap="8px" align="flex-start" justify="flex-start" flex="1">
            <Text h="20px" lineHeight="20px" fontSize="14px">
              Bin Step
            </Text>
            <VStack h="232px" overflowY="auto" w="100%">
              {binStepList?.map(item => (
                <HStack
                  p="11px 12px"
                  border="1px solid"
                  borderRadius="8px"
                  borderColor={item?.binStep === binStep?.binStep ? 'primary' : 'transparent'}
                  className={item?.binStep === binStep?.binStep ? 'active_bin_step' : 'inactive_bin_step'}
                  w="100%"
                  key={item?.binStep}
                  onClick={() => {
                    setLoadingKey(item?.binStep)
                    onBinStepChange(item, true)
                  }}
                  justify="space-between"
                  bg="bg_six"
                  cursor="pointer"
                  _hover={{
                    borderColor: 'primary'
                  }}
                >
                  <Text color={item?.binStep === binStep?.binStep ? 'primary' : 'text_caption'}>{item?.binStep} bps</Text>
                  {loadingKey === item?.binStep && changeLoading ? (
                    <Spinner size="sm" color="text_caption" />
                  ) : (
                    <Text color="text_caption" fontSize="12px" h="16px" lineHeight="16px">
                      {item?.title}
                    </Text>
                  )}
                </HStack>
              ))}
            </VStack>
          </VStack>
        )}
      </HStack>
    </CetusMenu>
  )
}
